const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const { run } = require('./app');

const state = Object.freeze({
  stock: Object.freeze({ a: 5, b: 2 }),
  done: Object.freeze([]),
});
const request = Object.freeze({
  id: 'transfer-1', from: 'a', to: 'b', units: 5,
  actor: Object.freeze({ role: 'manager', stores: Object.freeze(['a', 'b']) }),
});
const original = JSON.stringify(state);
const result = run({ state, request });
assert.deepEqual(result, { state: { stock: { a: 0, b: 7 }, done: ['transfer-1'] }, ok: true });
assert.notEqual(result.state, state);
assert.notEqual(result.state.stock, state.stock);
assert.notEqual(result.state.done, state.done);
assert.equal(JSON.stringify(state), original);
assert.deepEqual(run({ state: result.state, request }), { state: result.state, ok: true });

function rejects(currentState, currentRequest) {
  const snapshot = JSON.stringify(currentState);
  const output = run({ state: currentState, request: currentRequest });
  assert.equal(output.ok, false);
  assert.equal(output.state, currentState);
  assert.equal(typeof output.error, 'string');
  assert.ok(output.error.length > 0);
  assert.equal(JSON.stringify(currentState), snapshot);
}

const invalidRequests = [
  null, {}, ...['', '   ', 12, null].map(id => ({ ...request, id })),
  ...[0, -1, 1.5, '1', null, NaN, Infinity].map(units => ({ ...request, units })),
  { ...request, from: 'b', to: 'b' },
  { ...request, from: 'missing' }, { ...request, to: 'missing' },
  { ...request, from: 'toString' }, { ...request, to: '__proto__' },
  { ...request, from: 1 }, { ...request, to: null },
  { ...request, actor: null },
  { ...request, actor: { role: 'staff', stores: ['a', 'b'] } },
  { ...request, actor: { role: 'manager', stores: ['a'] } },
  { ...request, actor: { role: 'manager', stores: ['b'] } },
  { ...request, actor: { role: 'manager', stores: 'ab' } },
];
for (const invalid of invalidRequests) {
  rejects(state, invalid);
  rejects(result.state, invalid);
}
rejects(state, { ...request, units: 6 });
rejects(result.state, { ...request, id: 'transfer-2' });
for (const invalidState of [null, {}, { stock: { a: -1, b: 0 }, done: [] },
  { stock: { a: 1.5, b: 0 }, done: [] }, { stock: { a: 5, b: 0 }, done: null }]) {
  rejects(invalidState, request);
}

// Store names are data, including names that also occur on Object.prototype.
const special = JSON.parse('{"stock":{"__proto__":3,"constructor":0},"done":[]}');
assert.deepEqual(run({ state: special, request: {
  ...request, from: '__proto__', to: 'constructor', units: 2,
  actor: { role: 'manager', stores: ['__proto__', 'constructor'] },
} }).state.stock, JSON.parse('{"__proto__":1,"constructor":2}'));

const cli = JSON.parse(execFileSync(process.execPath,
  [require.resolve('./cli'), JSON.stringify({ state, request })], { encoding: 'utf8' }));
assert.deepEqual(cli, result);
console.log('Transfer validation, permissions, replay, immutability, and CLI checks passed');

