function run(input) {
  const { state, request } = input || {};
  const fail = error => ({ state, ok: false, error });
  const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
  const owns = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

  if (!isObject(state) || !isObject(state.stock) || !Array.isArray(state.done) ||
      !Object.values(state.stock).every(value => Number.isInteger(value) && value >= 0) ||
      !state.done.every(id => typeof id === 'string' && id.trim().length > 0)) {
    return fail('Invalid state');
  }
  if (!isObject(request) || typeof request.id !== 'string' || !request.id.trim()) {
    return fail('A non-empty request id is required');
  }
  const { id, from, to, units, actor } = request;
  if (!isObject(actor) || actor.role !== 'manager' || !Array.isArray(actor.stores)) {
    return fail('Manager permissions are required');
  }
  if (typeof from !== 'string' || typeof to !== 'string' || from === to ||
      !owns(state.stock, from) || !owns(state.stock, to)) {
    return fail('Source and destination must be different existing stores');
  }
  if (!actor.stores.includes(from) || !actor.stores.includes(to)) {
    return fail('Permission for both stores is required');
  }
  if (!Number.isInteger(units) || units <= 0) {
    return fail('Units must be a positive integer');
  }
  if (state.done.includes(id)) return { state, ok: true };
  if (state.stock[from] < units) return fail('Insufficient stock');

  const destinationStock = state.stock[to] + units;
  if (!Number.isFinite(destinationStock) || destinationStock - state.stock[to] !== units) {
    return fail('Destination stock cannot represent this transfer');
  }
  return {
    state: {
      ...state,
      stock: { ...state.stock, [from]: state.stock[from] - units, [to]: destinationStock },
      done: [...state.done, id],
    },
    ok: true,
  };
}

module.exports = { run };
